"""Main experiment runner for the shape-association stage (summary.txt's
proposed option (c), stage 1: "show a shape, agent names the digit").

Current settings (per project decision -- run as-is first, tune only if
the baseline results call for it):
  * 16x16 bitmaps, 5 digit classes (0-4), procedurally generated by
    digit_shapes.py -- no external dataset.
  * N_ROUNDS=400: full-mode connectome runs at ~1s/step (fly_api.py
    README), so 400 rounds x 3 fly.step()-equivalent calls (1 predict +
    2 x_teach_output trains, each of which itself runs `trials` forward
    passes) is already a real runtime budget. Check the accuracy curve
    before extending it, same discipline as the 113-state maze run.
  * Online setting throughout (predict-then-train each round, one shared
    example stream across all three agents) -- same protocol shape as
    run_gridworld.py / run_tictactoe.py's per-episode update() calls.

Writes results/shapes/shapes_results.csv (columns: round, agent, label,
predicted, correct, drift_pct) for a results/shapes/view_shapes.py-style
analysis script (not yet written) to consume, same convention as
gridworld/tictactoe's results/ directories.
"""
import sys
import os
import csv
import time

import sys, os
SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))   # .../my_experiments/scripts/shapes
ROOT = os.path.dirname(os.path.dirname(SCRIPT_DIR))       # .../my_experiments
for _p in (SCRIPT_DIR, ROOT):
    if _p not in sys.path:
        sys.path.insert(0, _p)

import numpy as np

from encoders.shapes.digit_shapes_encoder import sample
from agents.shapes.connectome_shape_agent import ConnectomeShapeAgent
from agents.shapes.linear_shape_agent import LinearShapeAgent
from agents.shapes.mlp_shape_agent import MLPShapeAgent
from encoders.shapes.digit_shapes_encoder import digit_bitmap  # add to your existing import line

N_ROUNDS = 400
N_DIGITS = 5
IMG_SIZE = 16
SLEEP_EVERY = 50  # connectome only, same periodic-sleep protocol as tic-tac-toe
PROGRESS_EVERY = 20

RESULTS_DIR = os.path.join(ROOT, "results", "shapes")


def main():
    os.makedirs(RESULTS_DIR, exist_ok=True)
    rng = np.random.default_rng(0)
    n_pixels = IMG_SIZE * IMG_SIZE

    agents = {
        "connectome": ConnectomeShapeAgent(digits=range(N_DIGITS)),
        "linear": LinearShapeAgent(n_pixels, N_DIGITS),
        "mlp": MLPShapeAgent(n_pixels, N_DIGITS),
    }

    calib_bitmaps = [digit_bitmap(d, size=IMG_SIZE) for d in range(N_DIGITS) for _ in range(4)]
    agents["connectome"].calibrate_baseline(calib_bitmaps)

    csv_path = os.path.join(RESULTS_DIR, "shapes_results.csv")
    t0 = time.time()
    with open(csv_path, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["round", "agent", "label", "predicted", "correct", "drift_pct"])

        for rnd in range(N_ROUNDS):
            label = int(rng.integers(N_DIGITS))
            bitmap = sample(label, rng, size=IMG_SIZE, noise_std=0.0)

            for name, agent in agents.items():
                pred, _ = agent.predict(bitmap)
                correct = int(pred == label)
                drift = f"{agent.drift_pct():.4f}" if hasattr(agent, "drift_pct") else ""
                w.writerow([rnd, name, label, pred, correct, drift])
                agent.train_on(bitmap, label)
            f.flush()

            if hasattr(agents["connectome"], "sleep") and (rnd + 1) % SLEEP_EVERY == 0:
                agents["connectome"].sleep()

            if (rnd + 1) % PROGRESS_EVERY == 0 or rnd == N_ROUNDS - 1:
                elapsed = time.time() - t0
                eta = elapsed / (rnd + 1) * (N_ROUNDS - rnd - 1)
                print(f"round {rnd + 1}/{N_ROUNDS} elapsed={elapsed:.0f}s eta={eta:.0f}s")

    print(f"wrote {csv_path}")


if __name__ == "__main__":
    main()
